37549.signature:
ZInQ.Compiler.Precision.JTriple.jdbl_affine.{u_1} {F : Type u_1} [Field F] (A : F) (P : JTriple F) (h2 : 2 ≠ 0)
  (hY : P.Y ≠ 0) (hZ : P.Z ≠ 0) :
  have x := P.X / P.Z ^ 2;
  have y := P.Y / P.Z ^ 3;
  have l := (3 * x ^ 2 + A) / (2 * y);
  (jdbl A P).Z ≠ 0 ∧
    l = (3 * P.X ^ 2 + A * P.Z ^ 4) / (jdbl A P).Z ∧
      (jdbl A P).X / (jdbl A P).Z ^ 2 = l ^ 2 - 2 * x ∧
        (jdbl A P).Y / (jdbl A P).Z ^ 3 = l * (x - (jdbl A P).X / (jdbl A P).Z ^ 2) - y

37553.signature:
ZInQ.Compiler.Precision.JTriple.jadd_affine.{u_1} {F : Type u_1} [Field F] (P Q : JTriple F) (hP : P.Z ≠ 0)
  (hQ : Q.Z ≠ 0) (hH : P.jH Q ≠ 0) :
  have x₁ := P.X / P.Z ^ 2;
  have y₁ := P.Y / P.Z ^ 3;
  have x₂ := Q.X / Q.Z ^ 2;
  have y₂ := Q.Y / Q.Z ^ 3;
  have l := (y₂ - y₁) / (x₂ - x₁);
  x₁ ≠ x₂ ∧
    (P.jadd Q).Z ≠ 0 ∧
      l = P.jΛ Q / (P.jadd Q).Z ∧
        (P.jadd Q).X / (P.jadd Q).Z ^ 2 = l ^ 2 - x₁ - x₂ ∧
          (P.jadd Q).Y / (P.jadd Q).Z ^ 3 = l * (x₁ - (P.jadd Q).X / (P.jadd Q).Z ^ 2) - y₁

